const $=s=>document.querySelector(s);
const photos=['314a774051f3317c','19c39684e7486572','8e1d28cf70d1f212','0e635f728f97cae2','cb3d9ea3eea2f98b','21b3e42050d0f1fb','db524063d942e51e','85f529fcae003780'];
const image=id=>`assets/${id}.jpg`;
const events=[['Weddings','A beautiful setting for the beginning of forever.',0,'Wedding'],['Engagements','An intimate, elegant stage for your yes.',3,'Engagement'],['Birthdays','Make the people you love feel celebrated.',6,'Birthday'],['Family Gatherings','Room for stories, laughter and togetherness.',1,'Family Function'],['Anniversaries','Return to your favourite memories in style.',4,'Anniversary'],['Festivals','Bring your traditions into a space made to glow.',3,'Family Function'],['Corporate Events','A polished setting for teams and milestones.',1,'Corporate'],['Private Parties','Your guest list, your mood, your moment.',4,'Family Function']];
$('#event-grid').innerHTML=events.map((e,i)=>`<button class="event-card" data-event="${e[3]}"><img loading="lazy" src="${image(photos[e[2]])}" alt="${e[0]}"><div class="card-caption"><small>0${i+1} &nbsp; ↗</small><h3>${e[0]}</h3><p>${e[1]}</p></div></button>`).join('');
const wa=text=>'https://wa.me/919355391931?text='+encodeURIComponent(text);
document.querySelectorAll('.whatsapp').forEach(a=>{a.href=wa('Hi Shreejee Banquet, I would like to enquire about '+(a.textContent.toLowerCase().includes('kitchen')?'Shreejee Kitchen catering and menu options.':a.textContent.toLowerCase().includes('setup')?'your venue setup options.':'booking the venue.'));a.target='_blank';a.rel='noopener';});
$('#menu-toggle').onclick=()=>{const open=$('nav').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',open);$('#menu-toggle').setAttribute('aria-label',open?'Close menu':'Open menu');$('#menu-toggle').textContent=open?'×':'☰';};
document.querySelectorAll('nav a').forEach(a=>a.onclick=()=>{$('nav').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');$('#menu-toggle').setAttribute('aria-label','Open menu');$('#menu-toggle').textContent='☰';});
const setups={Wedding:[1,'A graceful canvas for ceremonies, vows and a beautiful dinner with the people who matter most.'],Party:[4,'A warm, lively setting for birthdays, anniversaries and unforgettable evenings with your favourite people.'],Corporate:[1,'A polished, comfortable setting for teams, professional gatherings and important milestones.']};
$('#setup-tabs').onclick=e=>{const b=e.target.closest('button');if(!b)return;const name=b.dataset.setup;$('#setup-title').textContent=name+' Setup';$('#setup-photo').src=image(photos[setups[name][0]]);$('#setup-photo').alt=name+' setup';$('#setup-description').textContent=setups[name][1];document.querySelectorAll('#setup-tabs button').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b);});};
const gallery=[['The gathering hall','Venue',1],['Food worth gathering for','Food',2],['Details that set the tone','Decor',3],['A generous table','Food',5],['Make it yours','Celebrations',4],['Space for every story','Venue',6]];
let filtered=gallery,lightboxIndex=0;
$('#gallery-tabs').innerHTML=['All','Venue','Weddings','Decor','Food','Celebrations'].map((x,i)=>`<button data-filter="${x}" class="${i?'':'active'}" aria-pressed="${!i}">${x}</button>`).join('');
function renderGallery(){ $('#gallery-grid').innerHTML=filtered.map((g,i)=>`<button class="gallery-card" data-image="${i}"><img loading="lazy" src="${image(photos[g[2]])}" alt="${g[0]}"><div class="card-caption"><small>${g[1]} &nbsp; ↗</small><h3>${g[0]}</h3></div></button>`).join(''); }
$('#gallery-tabs').onclick=e=>{const b=e.target.closest('button');if(!b)return;filtered=b.dataset.filter==='All'?gallery:b.dataset.filter==='Weddings'?gallery.filter(g=>g[1]==='Decor'||g[1]==='Venue'):gallery.filter(g=>g[1]===b.dataset.filter);document.querySelectorAll('#gallery-tabs button').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b);});renderGallery();};
function showImage(){const g=filtered[lightboxIndex];$('#lightbox img').src=image(photos[g[2]]);$('#lightbox img').alt=g[0];$('#lightbox h3').textContent=g[0];}
$('#gallery-grid').onclick=e=>{const b=e.target.closest('button');if(!b)return;lightboxIndex=Number(b.dataset.image);showImage();$('#lightbox').showModal();};
$('#close-dialog').onclick=()=>$('#lightbox').close();$('#lightbox').onclick=e=>{if(e.target===$('#lightbox')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}};
function cycle(n){lightboxIndex=(lightboxIndex+n+filtered.length)%filtered.length;showImage();}$('#previous-image').onclick=()=>cycle(-1);$('#next-image').onclick=()=>cycle(1);$('#lightbox').onkeydown=e=>{if(e.key==='ArrowRight')cycle(1);if(e.key==='ArrowLeft')cycle(-1);};renderGallery();
const benefits=[['Spacious venue','Comfortable space for large gatherings.'],['Delicious food','Thoughtfully prepared catering for memorable celebrations.'],['Beautiful ambience','An elegant atmosphere that lets your occasion shine.'],['Convenient location','Located near DTC Bus Terminal, Najafgarh.'],['Thoughtful hospitality','A team focused on making events smooth and comfortable.'],['Flexible celebrations','Suitable for weddings, parties and family functions.']];
$('#benefits').innerHTML=benefits.map((b,i)=>`<div><small>0${i+1}</small><h3>${b[0]}</h3><p>${b[1]}</p></div>`).join('');
const faq=[['What events can be hosted at Shreejee Banquet?','Shreejee is designed for weddings, engagements, birthdays, anniversaries, family gatherings, festivals, corporate events and private parties.'],['How many guests can the venue accommodate?','The venue has an approximate capacity of 300+ guests. Please contact our team to confirm a suitable arrangement for your event.'],['Is catering available?','Yes. Shreejee Kitchen offers catering for celebrations and events. Contact our team to discuss your menu.'],['Can we customize the menu?','Please speak with our team about your preferences, dietary requirements and menu options.'],['Where is Shreejee Banquet located?','We are on Jharoda Road, near DTC Bus Terminal, Mahesh Garden, Najafgarh, Delhi 110043.'],['How can I check availability?','Fill in the booking query form or call 093553 91931. Our team will confirm availability for your preferred date.'],['Can I visit the venue before booking?','Contact us to arrange a venue visit at a convenient time.'],['Do you provide decoration and setup?','Please contact our team to discuss decoration, layouts and setup options for your celebration.']];
$('#faq-list').innerHTML=faq.map((f,i)=>`<details ${i?'':'open'}><summary>${f[0]}</summary><p>${f[1]}</p></details>`).join('');
let step=0,draft={event:'',guests:'',date:'',time:'',name:'',phone:'',notes:''};
try{draft={...draft,...JSON.parse(sessionStorage.getItem('shreejee-draft')||'{}')};}catch{}
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(){try{sessionStorage.setItem('shreejee-draft',JSON.stringify(draft));}catch{}}
const choices=(key,items)=>`<div class="choices">${items.map(x=>`<button type="button" data-key="${key}" data-value="${x}" aria-pressed="${draft[key]===x}" class="${draft[key]===x?'active':''}">${x}</button>`).join('')}</div>`;
const today=new Date();const minDate=[today.getFullYear(),String(today.getMonth()+1).padStart(2,'0'),String(today.getDate()).padStart(2,'0')].join('-');
function renderStep(){ $('.progress').innerHTML=[0,1,2,3,4].map(i=>`<span class="${i<=step?'active':''}" ${i===step?'aria-current="step"':''}>${i+1}</span>`).join('');$('#back').hidden=step===0;$('#continue').textContent=step===4?'Continue on WhatsApp →':'Continue →';const views=[`<h3>What are you celebrating?</h3>${choices('event',['Wedding','Engagement','Birthday','Anniversary','Corporate','Family Function','Venue Visit'])}`,`<h3>How many guests?</h3>${choices('guests',['50','100','150','200','250','300+'])}`,`<h3>When is your day?</h3><label>Preferred date<input name="date" type="date" min="${minDate}" required value="${esc(draft.date)}"></label><label>Preferred time<input name="time" type="time" required value="${esc(draft.time)}"></label>`,`<h3>How can we reach you?</h3><label>Your name<input name="name" autocomplete="name" required maxlength="100" value="${esc(draft.name)}"></label><label>Phone number<input name="phone" type="tel" autocomplete="tel" required pattern="[+0-9 ()-]{10,20}" maxlength="20" value="${esc(draft.phone)}"></label><label>Anything else?<textarea name="notes" maxlength="1500">${esc(draft.notes)}</textarea></label>`,`<h3>Your celebration at a glance.</h3><p>${esc(draft.event)} · ${esc(draft.guests)} guests<br>${esc(draft.date)} at ${esc(draft.time)}<br>${esc(draft.name)} · ${esc(draft.phone)}<br>${esc(draft.notes)}</p><p>Open WhatsApp to review and send your enquiry. Availability is confirmed by our team.</p>`];$('#step-content').innerHTML=views[step];validateStep();}
function validateStep(){const valid=step===0?!!draft.event:step===1?!!draft.guests:step===2?!!draft.date&&draft.date>=minDate&&!!draft.time:step===3?!!draft.name.trim()&&/^[+0-9 ()-]{10,20}$/.test(draft.phone):true;$('#continue').disabled=!valid;}
$('#booking').onclick=e=>{const b=e.target.closest('[data-key]');if(!b)return;draft[b.dataset.key]=b.dataset.value;persist();renderStep();};$('#booking').oninput=e=>{if(e.target.name){draft[e.target.name]=e.target.value;persist();validateStep();}};
$('#back').onclick=()=>{step=Math.max(0,step-1);renderStep();};$('#booking').onsubmit=e=>{e.preventDefault();if($('#continue').disabled)return;if(step<4){step++;renderStep();return;}const text=`Hi Shreejee Banquet, I would like to enquire about a booking.\nEvent: ${draft.event}\nGuests: ${draft.guests}\nDate: ${draft.date}\nTime: ${draft.time}\nName: ${draft.name}\nPhone: ${draft.phone}\nNotes: ${draft.notes}`;window.open(wa(text),'_blank','noopener');};
document.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>{draft.event=b.dataset.event;step=0;persist();renderStep();$('#enquire').scrollIntoView({behavior:'smooth'});});renderStep();
